for q in ['Tarantino','Quentin','Pulp Fiction','Django','Inglourious','Kill Bill']:
    hits=[]
    i=0
    while True:
        resp = apis.simple_note.search_notes(access_token=access_token, query=q, page_index=i, page_limit=20)
        if not resp:
            break
        hits.extend(resp)
        i+=1
        if i>10:
            break
    print('query', q, 'total_hits', len(hits))
    print('titles:', [h['title'] for h in hits[:10]])
